{
  "claims": [
    {
      "gene_symbol": "ASH1L",
      "confidence": 0.85,
      "cited_ids": [
        "pub:27434206"
      ],
      "rationale": "Human genetic mapping in a family with beta-thalassemia unlinked to the beta-globin cluster identified ASH1L as a candidate globin gene regulator, directly nominating it for subsequent functional validation."
    }
  ],
  "refusals": [
    {
      "gene_symbol": "CHD3",
      "reason": "Pre-cutoff literature links CHD3 to general chromatin remodeling via SENP1 without any evidence of a role in fetal hemoglobin regulation."
    },
    {
      "gene_symbol": "DNMT1",
      "reason": "Pre-cutoff evidence characterizes DNMT1 co-repressor complexes in erythroid cells, but does not provide candidate support for establishing it as a novel HbF regulator on or after the cutoff."
    },
    {
      "gene_symbol": "DNMT3A",
      "reason": "Pre-cutoff publications focus on hematopoietic stem cell differentiation and leukemia without linking DNMT3A to fetal hemoglobin regulation."
    },
    {
      "gene_symbol": "DNMT3B",
      "reason": "Available pre-cutoff studies address general DNA methylation and hematopoietic stem cell biology without evidence supporting a specific role in fetal hemoglobin control."
    },
    {
      "gene_symbol": "EIF2AK2",
      "reason": "The cited literature describes the heme-regulated eIF2alpha kinase (EIF2AK1/HRI) rather than implicating EIF2AK2 in fetal hemoglobin regulation."
    },
    {
      "gene_symbol": "EIF2AK3",
      "reason": "Pre-cutoff evidence addresses heme-regulated eIF2alpha kinase (HRI/EIF2AK1) biology rather than demonstrating a role for EIF2AK3 in fetal hemoglobin regulation."
